"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { requireUser } from "@/lib/auth";
import { PHASES } from "@/lib/focus/timer";
import { createClient } from "@/lib/supabase/server";

const sessionSchema = z
  .object({
    // Generated by the browser so a retried or duplicated log is stored once.
    id: z.uuid(),
    kind: z.enum(PHASES),
    taskId: z.uuid().nullable(),
    startedAt: z.iso.datetime(),
    endedAt: z.iso.datetime(),
    durationSeconds: z.int().min(1).max(7200),
    completed: z.boolean(),
  })
  .refine((s) => {
    const start = Date.parse(s.startedAt);
    const end = Date.parse(s.endedAt);
    // Plausible: ends after it starts, not in the future, and focused time
    // fits inside the wall-clock span.
    return end > start && end <= Date.now() + 60_000 && s.durationSeconds <= (end - start) / 1000 + 5;
  }, "Implausible session times.");

/** Records a finished focus or break period for the signed-in user. */
export async function logFocusSession(input: unknown): Promise<{ ok: boolean }> {
  await requireUser();
  const parsed = sessionSchema.safeParse(input);
  if (!parsed.success) return { ok: false };

  const s = parsed.data;
  const supabase = await createClient();
  const { error } = await supabase.from("focus_sessions").insert({
    id: s.id,
    kind: s.kind,
    task_id: s.taskId,
    started_at: s.startedAt,
    ended_at: s.endedAt,
    duration_seconds: s.durationSeconds,
    completed: s.completed,
  });
  // 23505: already stored by an earlier attempt.
  if (error && error.code !== "23505") return { ok: false };

  revalidatePath("/(app)", "layout");
  return { ok: true };
}
